//> using platform jvm
// Pending on jvm-constant-limits (queued): dotty's `BCodeUtils.checkConstantStringLength`
// and `genConstant`'s rejection branches refuse a string constant
// over 65535 bytes of modified UTF-8 and a class name too long
// ("String constant is too long for the JVM", a compile error, the .expected).
// An inline val of a string of 65536 ASCII characters, its length printed.
inline val text = ""
@main def run(): Unit = println(text.length)
